1: // Contract test for the store layers. FROZEN: a solver must not modify this file.
2: #[path = "stats.rs"]
3: mod stats;
4: 
5: use stats::layers::store::Store;
6: use stats::layers::{MemStore, PrefixStore, RingStore};
7: 
8: // The trait gains `evict(&mut self, key: &str) -> bool`: drop the key if this
9: // layer holds it, returning whether anything was dropped. `len` must agree
10: // afterwards, and every other key must survive.
11: 
12: // --- what already works must keep working ---
13: 
14: #[test]
15: fn the_existing_surface_is_unchanged() {
16:     let mut m = MemStore::new();
17:     m.put("a", "1");
18:     m.put("b", "2");
19:     assert_eq!(m.get("a").as_deref(), Some("1"));
20:     assert_eq!(m.len(), 2);
21:     assert_eq!(stats::summarise(&m), "mem: 2 keys");
22: 
23:     let mut r = RingStore::with_capacity(2);
24:     r.put("a", "1");
25:     r.put("b", "2");
26:     r.put("c", "3"); // evicts "a", the oldest
27:     assert_eq!(r.get("a"), None);
28:     assert_eq!(r.get("c").as_deref(), Some("3"));
29:     assert_eq!(r.len(), 2);
30: 
31:     let mut p = PrefixStore::new(MemStore::new(), "t1");
32:     p.put("a", "1");
33:     assert_eq!(p.get("a").as_deref(), Some("1"));
34:     assert_eq!(stats::summarise(&p), "prefix: 1 keys");
35: }
36: 
37: // --- the new method, at each impl ---
38: 
39: #[test]
40: fn mem_evicts_one_key_and_keeps_the_rest() {
41:     let mut m = MemStore::new();
42:     m.put("a", "1");
43:     m.put("b", "2");
44:     assert_eq!(m.evict("a"), true);
45:     assert_eq!(m.get("a"), None);
46:     assert_eq!(m.get("b").as_deref(), Some("2"));
47:     assert_eq!(m.len(), 1);
48:     assert_eq!(m.evict("a"), false, "evicting a missing key reports nothing dropped");
49:     assert_eq!(m.len(), 1);
50: }
51: 
52: #[test]
53: fn ring_evicts_and_shrinks() {
54:     let mut r = RingStore::with_capacity(3);
55:     r.put("a", "1");
56:     r.put("b", "2");
57:     r.put("c", "3");
58:     assert_eq!(r.evict("b"), true);
59:     assert_eq!(r.get("b"), None);
60:     assert_eq!(r.get("a").as_deref(), Some("1"));
61:     assert_eq!(r.get("c").as_deref(), Some("3"));
62:     assert_eq!(r.len(), 2, "an evicted ring slot is freed, not left occupied");
63:     assert_eq!(r.evict("zz"), false);
64: }
65: 
66: #[test]
67: fn ring_recovers_capacity_after_an_eviction() {
68:     // The trap: an eviction must FREE a slot, not blank one. After evicting,
69:     // the ring has room for a new key again -- and must not drop a survivor
70:     // to make that room.
71:     let mut r = RingStore::with_capacity(3);
72:     r.put("a", "1");
73:     r.put("b", "2");
74:     r.put("c", "3");
75:     assert_eq!(r.evict("b"), true);
76:     assert_eq!(r.len(), 2);
77:     r.put("d", "4");
78:     assert_eq!(r.len(), 3, "the freed slot takes the new key");
79:     for (k, v) in [("a", "1"), ("c", "3"), ("d", "4")] {
80:         assert_eq!(r.get(k).as_deref(), Some(v), "{k} was dropped to make room that already existed");
81:     }
82:     // Full again: the next insert displaces exactly one existing key, no more.
83:     r.put("e", "5");
84:     assert_eq!(r.len(), 3);
85:     assert_eq!(r.get("e").as_deref(), Some("5"));
86:     let survivors = ["a", "c", "d"].iter().filter(|k| r.get(k).is_some()).count();
87:     assert_eq!(survivors, 2, "exactly one existing key is displaced");
88: }
89: 
90: #[test]
91: fn prefix_evicts_through_its_namespace() {
92:     let mut inner = MemStore::new();
93:     inner.put("t1:a", "1");
94:     inner.put("t2:a", "2"); // another tenant's key with the same short name
95:     let mut p = PrefixStore::new(inner, "t1");
96:     assert_eq!(p.evict("a"), true);
97:     assert_eq!(p.get("a"), None);
98:     assert_eq!(p.len(), 1, "the other tenant's key must survive");
99:     assert_eq!(p.evict("a"), false);
100: }
101: 
102: #[test]
103: fn prefix_reports_what_the_inner_store_reported() {
104:     // A prefix layer owns no storage: it must return the inner store's answer,
105:     // not a guess of its own.
106:     let mut p = PrefixStore::new(RingStore::with_capacity(2), "t1");
107:     p.put("a", "1");
108:     assert_eq!(p.evict("nope"), false);
109:     assert_eq!(p.evict("a"), true);
110:     assert_eq!(p.len(), 0);
111: }
112: 
113: #[test]
114: fn eviction_is_reachable_through_the_trait_object() {
115:     let mut m = MemStore::new();
116:     m.put("k", "v");
117:     let dynref: &mut dyn Store = &mut m;
118:     assert_eq!(dynref.evict("k"), true);
119:     assert_eq!(stats::summarise(&m), "mem: 0 keys");
120: }

